mapper.select:
SELECT p.project_sq as projectSq, p.project_ttl as projectTitle, c.company_nm as companyName, GROUP_CONCAT(cc1.common_code_nm) as jobType, a.address, a.detail_address as detailAddress, a.latitude, a.longitude, p.project_salary as projectSalary, DATE_FORMAT(p.project_start_dt, '%Y-%m-%d') as projectStartDate, DATE_FORMAT(p.project_end_dt, '%Y-%m-%d') as projectEndDate, DATE_FORMAT(p.project_recruit_end_dt, '%Y-%m-%d') as recruitEndDt, a.sigungu, ROUND( 6371 * acos( cos(radians(#{userLat})) * cos(radians(a.latitude)) * cos(radians(a.longitude) - radians(#{userLon})) + sin(radians(#{userLat})) * sin(radians(a.latitude)) ), 1 ) as distance FROM TBL_PROJECT_M p INNER JOIN TBL_ADDRESS_S a ON p.address_sq = a.address_sq INNER JOIN TBL_COMPANY_S c ON p.company_sq = c.company_sq INNER JOIN TBL_PROJECT_RECRUIT_JOB_ROLE_S pjr ON p.project_sq = pjr.project_sq INNER JOIN TBL_COMMON_CODE_C cc1 ON pjr.recruit_job_position_type_cd = cc1.common_code_sq WHERE p.project_is_deleted_yn = 'N' AND p.project_activate_yn = 'Y' AND p.project_recruit_end_dt >= CURDATE() AND (
(6371 * acos( cos(radians(#{userLat})) * cos(radians(a.latitude)) * cos(radians(a.longitude) - radians(#{userLon})) + sin(radians(#{userLat})) * sin(radians(a.latitude)) )) <= #{radius} )
AND cc1.common_code_nm = #{jobType}
AND ( p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') OR c.company_nm LIKE CONCAT('%', #{searchKeyword}, '%') )
GROUP BY p.project_sq, p.project_ttl, c.company_nm, a.address, a.detail_address, a.latitude, a.longitude, p.project_salary, p.project_start_dt, p.project_end_dt, p.project_recruit_end_dt, a.sigungu ORDER BY (
6371 * acos( cos(radians(#{userLat})) * cos(radians(a.latitude)) * cos(radians(a.longitude) - radians(#{userLon})) + sin(radians(#{userLat})) * sin(radians(a.latitude)) ) ) ASC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT p.project_sq) FROM TBL_PROJECT_M p INNER JOIN TBL_ADDRESS_S a ON p.address_sq = a.address_sq INNER JOIN TBL_COMPANY_S c ON p.company_sq = c.company_sq INNER JOIN TBL_PROJECT_RECRUIT_JOB_ROLE_S pjr ON p.project_sq = pjr.project_sq INNER JOIN TBL_COMMON_CODE_C cc1 ON pjr.recruit_job_position_type_cd = cc1.common_code_sq WHERE p.project_is_deleted_yn = 'N' AND p.project_activate_yn = 'Y' AND p.project_recruit_end_dt >= CURDATE() AND ( (6371 * acos( cos(radians(#{userLat})) * cos(radians(a.latitude)) * cos(radians(a.longitude) - radians(#{userLon})) + sin(radians(#{userLat})) * sin(radians(a.latitude)) )) <= #{radius} )
AND cc1.common_code_nm = #{jobType}
AND ( p.project_ttl LIKE CONCAT('%', #{searchKeyword}, '%') OR c.company_nm LIKE CONCAT('%', #{searchKeyword}, '%') )
